%% 
idx1 = data(:,1) > 0.12 & data(:,1) < 1.0; 
t = data(idx1,1)-0.11; % Time
id = data(idx1,2); % Current
plot(t,id);
% id : gemessener d-Achsenstrom
%% Zeitpunkt der Störung
t0 = t(1);           % ggf. anpassen
tt = t - t0;

%% Modell:
% id = i_inf + A*exp(-t/Td'') + B*exp(-t/Td')

model = @(x,t) x(1) + ...
               x(2)*exp(-t/x(3)) + ...
               x(4)*exp(-t/Td1);

% x = [i_inf  A  Td''  B]

%% Startwerte
i_inf0 = mean(id(end-100:end));
A0     = id(1)-i_inf0;
Td20   = 0.02;          % 20 ms Starting value for optimization
B0     = 0;

x0 = [i_inf0 A0 Td20 B0];

%% Grenzen
lb = [-Inf -Inf 0.001 -Inf];
ub = [ Inf  Inf 0.2    Inf];
options.FunctionTolerance = 1.000000e-08
%% Fit
opts = optimoptions('lsqcurvefit','Display','iter');

x = lsqcurvefit(model,x0,tt,id,lb,ub,opts);

%% Ergebnisse
i_inf = x(1);
A     = x(2);
Td2   = x(3);
B     = x(4);

fprintf('Td'''' = %.5f s\n',Td2);

%% Vergleich
figure
plot(tt,id,'b','LineWidth',1.5)
hold on
plot(tt,model(x,tt),'r--','LineWidth',2)
grid on
xlabel('time [s]')
ylabel('i_d')
legend('Simulation','Fit')
title(sprintf('Td'''' = %.4f s',Td2))